export type Disease = {
  name: string;
  slug: string;
  desc: string;
  fullDesc: string;
  origin: string;
  treatment: string;
  recommendations: string;
};

export type DiseaseCategory = {
  id: string;
  title: string;
  subtitle: string;
  quote: string;
  image: string;
  diseases: Disease[];
};

// Helper to generate slug from name
export function generateSlug(name: string): string {
  return name
    .toLowerCase()
    .replace(/[()\/]/g, "")
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

// Helper to find disease by category and slug
export function findDisease(categoryId: string, slug: string): { category: DiseaseCategory; disease: Disease } | null {
  const category = diseaseCategories.find((c) => c.id === categoryId);
  if (!category) return null;
  const disease = category.diseases.find((d) => d.slug === slug);
  if (!disease) return null;
  return { category, disease };
}

